128	    public long insertOrder(CurtailOrder order) {
129	        KeyHolder keyHolder = new GeneratedKeyHolder();
130	        jdbc.update(connection -> {
131	            PreparedStatement ps = connection.prepareStatement("""
132	                    INSERT INTO curtail_order
133	                        (order_no, farm_code, request_id, fingerprint, target_power_kw,
134	                         status, current_cycle_no, superseded_by_order_id, active_flag,
135	                         received_at, settled_at, plan_version_id, plan_version_no,
136	                         plan_date, segment_index)
137	                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
138	                    """, Statement.RETURN_GENERATED_KEYS);
139	            ps.setString(1, order.getOrderNo());
140	            ps.setString(2, order.getFarmCode());
141	            ps.setString(3, order.getRequestId());
142	            ps.setString(4, order.getFingerprint());
143	            ps.setInt(5, order.getTargetPowerKw());
144	            ps.setString(6, order.getStatus().name());
145	            ps.setInt(7, order.getCurrentCycleNo());
146	            if (order.getSupersededByOrderId() == null) {
147	                ps.setNull(8, java.sql.Types.BIGINT);
148	            } else {
149	                ps.setLong(8, order.getSupersededByOrderId());
150	            }
151	            // 新指令一律先以非执行中（active_flag=NULL）插入，由服务在旧指令作废后显式置 Y，
152	            // 保证同一事务内不会出现两个执行中指令。
153	            ps.setNull(9, java.sql.Types.CHAR);
154	            ps.setTimestamp(10, Timestamp.from(order.getReceivedAt()));
155	            ps.setTimestamp(11, order.getSettledAt() == null ? null : Timestamp.from(order.getSettledAt()));
156	            if (order.getPlanVersionId() == null) {
157	                ps.setNull(12, java.sql.Types.BIGINT);
158	            } else {
159	                ps.setLong(12, order.getPlanVersionId());
160	            }
161	            if (order.getPlanVersionNo() == null) {
162	                ps.setNull(13, java.sql.Types.INTEGER);
163	            } else {
164	                ps.setInt(13, order.getPlanVersionNo());
165	            }
166	            if (order.getPlanDate() == null) {
167	                ps.setNull(14, java.sql.Types.DATE);
168	            } else {
169	                ps.setDate(14, java.sql.Date.valueOf(order.getPlanDate()));
170	            }
171	            if (order.getSegmentIndex() == null) {
172	                ps.setNull(15, java.sql.Types.INTEGER);
173	            } else {
174	                ps.setInt(15, order.getSegmentIndex());
175	            }
176	            return ps;
177	        }, keyHolder);
178	        Number key = keyHolder.getKey();
179	        long id = key == null ? 0L : key.longValue();
180	        order.setId(id);
181	        return id;
182	    }
