40	 * 当前指针原子替换、版本查询。发布与计划绑定指令受理共用风场行锁，
41	 * 保证竞争时校验的版本与指令冻结基数一致。
42	 */
43	@Service
44	public class PlanService {
45	
46	    static final int SEGMENTS_PER_DAY = 96;
47	
48	    private final ServiceClock clock;
49	    private final TurbineRepository turbineRepository;
50	    private final PlanRepository planRepository;
51	    private final IdempotentRepository idempotentRepository;
52	    private final ObjectMapper objectMapper;
53	
54	    public PlanService(ServiceClock clock,
55	                       TurbineRepository turbineRepository,
56	                       PlanRepository planRepository,
57	                       IdempotentRepository idempotentRepository,
58	                       ObjectMapper objectMapper) {
59	        this.clock = clock;
60	        this.turbineRepository = turbineRepository;
61	        this.planRepository = planRepository;
62	        this.idempotentRepository = idempotentRepository;
63	        this.objectMapper = objectMapper;
64	    }
