66	    /**
67	     * 发布日前计划版本：
68	     * 整版须恰好覆盖 96 段 × 全场每台机组各一条，非负且不超过合成装机，否则整版拒绝（422）；
69	     * expectedVersion 首版传 1，其后须等于当前最新版本号，成功发布版本加 1，不匹配 409；
70	     * 同 requestId 同参重放首次冻结结果，异参 409；业务失败不占键。
71	     */
72	    @Transactional
73	    public PlanPublishResponse publish(PlanPublishRequest request) {
74	        Instant now = clock.now();
75	        // 指纹含调用方给出的精确发布时刻（业务参数的一部分），重放同参稳定、异时刻 409；
76	        // 版本落库时间仍取服务端受理时钟。
77	        String fingerprint = fingerprint(request, request.operateAt());
78	
79	        IdempotentRecord existing = idempotentRepository.findByRequestId(request.requestId());
80	        if (existing != null) {
81	            return resolvePublishIdempotent(existing, fingerprint);
82	        }
83	
84	        if (!turbineRepository.lockFarmRow(request.farmCode())) {
85	            throw new ApiNotFoundException("风场不存在：" + request.farmCode());
86	        }
87	
88	        existing = idempotentRepository.findByRequestId(request.requestId());
89	        if (existing != null) {
90	            return resolvePublishIdempotent(existing, fingerprint);
91	        }
92	
93	        List<Turbine> turbines = turbineRepository.findByFarm(request.farmCode());
94	        if (turbines.isEmpty()) {
95	            throw new ApiNotFoundException("风场不存在：" + request.farmCode());
96	        }
97	
98	        // 先做全部业务校验（失败抛 422，不写幂等占位——失败不占键），再判定版本与写入。
99	        Map<Integer, Map<String, Integer>> bySegment = validateWholePlan(request, turbines);
100	
101	        // expectedVersion 为调用方期望本次成功后占用（创建）的版本号：版本从 1 开始，成功变更加 1。
102	        // 无版本时仅允许 1；其后必须为当前最大版本号 +1。风场行锁内判定，并发竞争仅一方满足。
103	        Integer currentMax = planRepository.findMaxVersionNo(request.farmCode(), request.planDate());
104	        int newVersionNo;
105	        if (currentMax == null) {
106	            if (request.expectedVersion() != 1) {
107	                throw new ApiConflictException(
108	                        "该风场该日尚无计划版本，expectedVersion 必须为 1，实际为 "
109	                                + request.expectedVersion());
110	            }
111	            newVersionNo = 1;
112	        } else {
113	            if (request.expectedVersion() != currentMax + 1) {
114	                throw new ApiConflictException(
115	                        "expectedVersion=" + request.expectedVersion()
116	                                + " 与下一个版本号 " + (currentMax + 1) + " 不一致（当前最新 v"
117	                                + currentMax + "）");
118	            }
119	            newVersionNo = currentMax + 1;
120	        }
121	
122	        IdempotentRecord record = new IdempotentRecord();
123	        record.setRequestId(request.requestId());
124	        record.setBizType("PLAN");
125	        record.setFingerprint(fingerprint);
126	        record.setCreatedAt(now);
127	        record.setResponseBody("");
128	        if (!idempotentRepository.tryInsert(record)) {
129	            return resolvePublishIdempotent(
130	                    idempotentRepository.findByRequestId(request.requestId()), fingerprint);
131	        }
132	
133	        PlanVersion version = new PlanVersion();
134	        version.setFarmCode(request.farmCode());
135	        version.setPlanDate(request.planDate());
136	        version.setVersionNo(newVersionNo);
137	        version.setRequestId(request.requestId());
138	        version.setFingerprint(fingerprint);
139	        version.setPublishedAt(now);
140	        long versionId = planRepository.insertVersion(version);
141	
142	        Map<String, Long> turbineIdByCode = turbines.stream()
143	                .collect(Collectors.toMap(Turbine::getTurbineCode, Turbine::getId));
144	        List<PlanSegment> entities = new ArrayList<>();
145	        for (int idx = 0; idx < SEGMENTS_PER_DAY; idx++) {
146	            for (Turbine t : turbines) {
147	                PlanSegment s = new PlanSegment();
148	                s.setVersionId(versionId);
149	                s.setSegmentIndex(idx);
150	                s.setTurbineId(turbineIdByCode.get(t.getTurbineCode()));
151	                s.setPowerKw(bySegment.get(idx).get(t.getTurbineCode()));
152	                entities.add(s);
153	            }
154	        }
155	        planRepository.insertSegments(versionId, entities);
156	        // 原子替换当前指针：旧当前版本置历史，新版本置当前，历史全部保留。
157	        planRepository.swapCurrent(request.farmCode(), request.planDate(), versionId);
158	
159	        PlanPublishResponse response = new PlanPublishResponse(versionId, request.farmCode(),
160	                request.planDate(), newVersionNo, true, now, entities.size(), turbines.size(),
161	                request.requestId(), false);
162	        idempotentRepository.updateRefAndResponse(request.requestId(), versionId, toJson(response));
163	        return response;
164	    }
