3	import java.time.Instant;
4	
5	/**
6	 * 风电机组。
7	 * ratedPowerKw 装机容量（kW）；technicalMinKw 技术出力下限（kW，额定的 15%）；
8	 * availablePowerKw 最新可用出力（kW），随执行回报刷新。
9	 */
10	public class Turbine {
11	
12	    private Long id;
13	    private String farmCode;
14	    private String turbineCode;
15	    private int ratedPowerKw;
16	    private int technicalMinKw;
17	    private int availablePowerKw;
18	    private Instant updatedAt;
19	
20	    public Long getId() {
21	        return id;
