7	 * 结构化、无歧义的规范编码：TLV（类型标记 + UTF-8 字节长度前缀 + 内容）。
8	 * 即使合法文本本身含 ":" 或任何分隔符也不会产生歧义——长度前缀决定边界，
9	 * 且文本/整数/时刻/布尔使用不同类型标记，"1"、1、true 不会互相混淆。
10	 * 集合以元素计数前缀包裹，嵌套结构同样无歧义。
11	 */
12	public final class Canonical {
13	
14	    private Canonical() {
15	    }
16	
17	    /** 文本 token：t&lt;字节数&gt;:&lt;UTF-8 文本&gt;。 */
18	    public static String str(String value) {
19	        byte[] bytes = value == null ? new byte[0] : value.getBytes(StandardCharsets.UTF_8);
20	        return "t" + bytes.length + ":" + (value == null ? "" : value);
21	    }
22	
23	    /** 整数 token：i&lt;十进制长度&gt;:&lt;十进制值&gt;。 */
24	    public static String integer(long value) {
25	        String text = Long.toString(value);
26	        return "i" + text.length() + ":" + text;
27	    }
28	
29	    /** 布尔 token：b&lt;长度&gt;:true|false。 */
30	    public static String bool(boolean value) {
31	        String text = Boolean.toString(value);
32	        return "b" + text.length() + ":" + text;
33	    }
34	
35	    /**
36	     * 精确时刻 token：以 epoch 毫秒编码（与库内 TIMESTAMP 精度一致），
37	     * 不依赖时区与格式字符串。
38	     */
39	    public static String instant(java.time.Instant value) {
40	        String text = Long.toString(value.toEpochMilli());
41	        return "m" + text.length() + ":" + text;
42	    }
43	
44	    /** UTC 日期 token：固定 ISO yyyy-MM-dd。 */
45	    public static String date(java.time.LocalDate value) {
46	        String text = value.toString();
47	        return "d" + text.length() + ":" + text;
48	    }
49	
50	    /**
51	     * 有序字段序列（对象）：o&lt;字段数&gt;: 后接“键 token + 值 token”交替。
52	     * 字段顺序由调用方显式给出；值本身为任意规范 token 或嵌套对象/列表。
